use sqlx::PgPool;use uuid::Uuid;
pub async fn commit_staged(pool:&PgPool,tenant_id:Uuid,import_id:Uuid,lease_owner:&str)->Result<bool,sqlx::Error>{let mut tx=pool.begin().await?;let fenced=sqlx::query("SELECT 1 FROM work_items w JOIN archive_imports a ON a.tenant_id=w.tenant_id AND a.id=(w.payload->>'import_id')::uuid WHERE w.tenant_id=$1 AND a.id=$2 AND w.lease_owner=$3 AND w.status='running' FOR UPDATE").bind(tenant_id).bind(import_id).bind(lease_owner).fetch_optional(&mut *tx).await?.is_some();if !fenced{return Ok(false)}
let rows=sqlx::query("SELECT record_json,content_hmac FROM import_staging_records WHERE tenant_id=$1 AND import_id=$2 ORDER BY source_revision_id").bind(tenant_id).bind(import_id).fetch_all(&mut *tx).await?;for row in rows{use sqlx::Row;let v:serde_json::Value=row.try_get("record_json")?;let h:Vec<u8>=row.try_get("content_hmac")?;let logical=v["source_logical_id"].as_str().unwrap_or_default();let revision=v["source_revision_id"].as_str().unwrap_or_default();let platform=v["platform"].as_str().unwrap_or_default();let body=v["body"].as_str();let title=v["title"].as_str();let id:Uuid=sqlx::query_scalar("INSERT INTO content_items(tenant_id,user_id,platform,kind,authorship,title,body,source_logical_id,source_revision_id,record_type,text_format,content_state,content_hmac,relation_confidence) SELECT tenant_id,user_id,$3,$4,$5,$6,$7,$8,$9,$4,$10,$11,$12,$13 FROM archive_imports WHERE tenant_id=$1 AND id=$2 ON CONFLICT(tenant_id,source_logical_id) WHERE source_logical_id IS NOT NULL DO UPDATE SET source_revision_id=EXCLUDED.source_revision_id,title=EXCLUDED.title,body=EXCLUDED.body,content_hmac=EXCLUDED.content_hmac,updated_at=now() RETURNING id").bind(tenant_id).bind(import_id).bind(platform).bind(v["record_type"].as_str().unwrap_or("post")).bind(v["authorship"].as_str().unwrap_or("owner_authored")).bind(title).bind(body).bind(logical).bind(revision).bind(v["text_format"].as_str().unwrap_or("standard")).bind(v["state"].as_str().unwrap_or("active")).bind(h).bind(v["relation_confidence"].as_str().unwrap_or("none")).fetch_one(&mut *tx).await?;sqlx::query("INSERT INTO archive_import_content_items(tenant_id,import_id,content_item_id) VALUES($1,$2,$3) ON CONFLICT DO NOTHING").bind(tenant_id).bind(import_id).bind(id).execute(&mut *tx).await?;}
let n=sqlx::query("UPDATE archive_imports SET status='ready',item_count=(SELECT count(*) FROM archive_import_content_items WHERE tenant_id=$1 AND import_id=$2),finished_at=now(),updated_at=now() WHERE tenant_id=$1 AND id=$2").bind(tenant_id).bind(import_id).execute(&mut *tx).await?.rows_affected();sqlx::query("DELETE FROM import_staging_records WHERE tenant_id=$1 AND import_id=$2").bind(tenant_id).bind(import_id).execute(&mut *tx).await?;sqlx::query("DELETE FROM import_index_entries WHERE tenant_id=$1 AND import_id=$2").bind(tenant_id).bind(import_id).execute(&mut *tx).await?;tx.commit().await?;Ok(n==1)}
